You can call helper functions to assist you with the computation. 
These functions will be counted against the length limits.


### Code:
def f(inputs):
    factors = {}
    for i in inputs:
        if i == 0:
            break
        for j in range(2, i+1):
            while i % j == 0 and j not in factors:
                factors[j] = []
                while i % j == 0:
                    factors[j].append(j)
                    i //= j
    for k in factors:
        factors[k] = sorted(factors[k])
    sort_by_count = sorted(factors.items(),key=lambda x: len(x[1]), reverse = True)
    if not sort_by_count:
        return 0
    return sort_by_count[0][0]

